(function(){window.Bundles=[{id:'everyday',name:'Everyday Essentials',ids:['dew-gel-cleanser','daily-lotion','fluid-shield'],price:3490,image:'../assets/images/bundles/bundle-1.jpg',skin:['Normal','Combination']},{id:'hydration',name:'Hydration Routine',ids:['cloudmilk-cleanser','waterline-serum','ceramide-cloud'],price:3690,image:'../assets/images/bundles/bundle-2.jpg',skin:['Dry','Sensitive']},{id:'balanced',name:'Balanced Skin Set',ids:['dew-gel-cleanser','balance-niacinamide','water-gel'],price:3290,image:'../assets/images/bundles/bundle-3.jpg',skin:['Oily','Combination']},{id:'morning',name:'Morning Routine',ids:['morning-c-serum','daily-lotion','mineral-shield'],price:3890,image:'../assets/images/bundles/bundle-4.jpg',skin:['Normal','Dry']},{id:'evening',name:'Quiet Evening Set',ids:['cleansing-balm','barrier-serum','squalane-cream'],price:3850,image:'../assets/images/bundles/bundle-5.jpg',skin:['Dry','Sensitive']},{id:'travel',name:'Travel Essentials',ids:['oat-veil-cleanser','water-gel','fluid-shield'],price:3190,image:'../assets/images/bundles/bundle-6.jpg',skin:['All']}];const root=document.querySelector('#bundleGrid');if(!root)return;root.innerHTML=Bundles.map(b=>{const products=b.ids.map(getProduct),total=products.reduce((s,p)=>s+p.price,0),saving=total-b.price;return `<article class="bundle-card"><img src="${b.image}" alt="${b.name}" loading="lazy"><div class="bundle-body"><span class="eyebrow">${b.skin.join(' · ')}</span><h3>${b.name}</h3><p>${products.map(p=>p.name).join(' + ')}</p><div class="bundle-price"><strong class="price">₹${b.price.toLocaleString('en-IN')}</strong><span class="old-price">₹${total.toLocaleString('en-IN')}</span></div><p class="saving">Save ₹${saving.toLocaleString('en-IN')}</p><button class="btn btn-primary add-bundle" data-id="${b.id}">Add Bundle to Bag</button></div></article>`}).join('');root.addEventListener('click',e=>{const btn=e.target.closest('.add-bundle');if(!btn)return;const b=Bundles.find(x=>x.id===btn.dataset.id);Cart.add(b.id,1,'bundle',{name:b.name,price:b.price,image:b.image,ids:b.ids})})})();
